import logging
import sys
import time
import six

from ute_common_abstract_core.exceptions import InvalidConfigurationContent
from ute_ue.exceptions import CannotCreateQualcommUe
from ute_ue.lteuepool import CfgFileBasedUePool
from ta_ue_plugin_qualcomm.ue.qualcomm.pc_server import pc_server_exceptions
from ta_ue_plugin_qualcomm.ue.qualcomm.pc_server.qxdm_pc import QxdmUePcHandler
from ta_ue_plugin_qualcomm.ue.qualcomm.pc_server.server_commands import TEST
from ta_ue_plugin_qualcomm.ue.qualcomm.qualcomm_ue import QualcommUe
from ta_ue_plugin_qualcomm.utils import get_vm_ip_address, compare_versions
from ute_ue.utils.vm_utils import get_vm_user, get_vm_password, get_vm_ssh_port, get_vm_test_logs_dir
from ta_ue_plugin_qualcomm import get_plugin_version, get_required_ue_pc_server_version
from ta_ue_plugin_qualcomm.ue.qualcomm.pc_server.pc_server_exceptions import TimeoutExceededException
from ta_ue_plugin_qualcomm.ue.qualcomm.qualcomm_ue_config_validator import QualcommUeConfigValidator


CONSTRUCTOR_PARAMETERS = 'CONSTRUCTOR_PARAMETERS'


class QualcommUePool(CfgFileBasedUePool):
    """Qualcomm Ue Pool"""

    def __init__(self, config_file_path=None, inline_config=None):
        """
        :param config_file_path:
        :param inline_config:
        """
        if inline_config is None:
            inline_config = {}
        super(QualcommUePool, self).__init__(config_file_path, inline_config)
        self.ue_pc_store = {}
        self.logger = self._get_logger()

    def create_device(self, ue_name, ue_config):
        """
        Create instance of ue

        :param ue_name:
        :param ue_config:
        :return: ue instance
        """
        try:
            self.config_validator = QualcommUeConfigValidator(ue_name, ue_config)
            ue_config = dict(self.config_validator.validate())
            config = ue_config[CONSTRUCTOR_PARAMETERS]['configuration']
            serial_number = ue_config[CONSTRUCTOR_PARAMETERS].get('serial_number', '')
            self._ensure_connected_to_ue_pc(config, serial_number)
            ue_pc_host, ue_pc_handler = self._get_handler_for_ue_pc(config)
            return self._new_qualcomm_ue(ue_name, ue_config, serial_number, ue_pc_handler)

        except KeyError as e:
            raise InvalidConfigurationContent("Configuration is not valid for Qualcomm UE: %s. Expected keyword: %s" % (ue_name, e.args[0]))
        except CannotCreateQualcommUe:
            self._teardown_ue_pc(ue_pc_host)
            self.logger.error("{} was not created".format(ue_name))
            raise

    def _get_logger(self):
        return logging.getLogger('ute_ue')

    def _get_handler_for_ue_pc(self, config):
        ue_pc_host = config['ue_pc_host']
        ue_pc_handler = self.ue_pc_store[ue_pc_host]['qxdm_ue_pc_handler']
        return ue_pc_host, ue_pc_handler

    def _new_qualcomm_ue(self, ue_name, ue_config, serial_number, ue_pc_handler):

        return QualcommUe(ue_name, ue_config, serial_number, ue_pc_handler)

    def _ensure_connected_to_ue_pc(self, config, serial_number):
        ue_pc_host = config['ue_pc_host']
        if ue_pc_host not in self.ue_pc_store:
            try:
                self._create_connected_ue_pc_client(config, serial_number)
            except Exception as e:
                self.logger.exception(e, exc_info=True)
                six.reraise(e.__class__, e, sys.exc_info()[2])

    def _create_connected_ue_pc_client(self, config, serial_number):
        ue_pc_handler = QxdmUePcHandler()
        ue_pc_host = config['ue_pc_host']
        ue_com_port = config['com_port']
        ue_type = config['ue_type']
        self.ue_pc_store[ue_pc_host] = self._build_dict_with_params(ue_pc_handler)
        ue_pc_handler.setup_connection_with_ue_pc_server(host=config['ue_pc_host'], port_dict=config['port_dict'])
        qxdm_version = config.get('qxdm_version', 4)

        try:
            self._check_server_version_compatibility(ue_pc_handler)
            if ue_type == "LINUX":
                self._check_ue_com_port(ue_pc_host, ue_com_port)
            else:
                self._check_ue_serial_number(ue_pc_host, serial_number)
                self._check_ue_com_port(ue_pc_host, ue_com_port)
            status, _ = ue_pc_handler.send(TEST.START, qxdm_version=qxdm_version, licence_type=config.get('licence_type', '4G'))
            self.logger.info("TEST.START status: {}".format(status))
            if status:
                time.sleep(5)
                self.logger.info("UE PC Server preparation complete")
            else:
                raise pc_server_exceptions.TestHandlingException(
                    "UE PC Server preparation failed. Failed to properly handle test starting procedure.")
        except Exception as e:
            self.logger.exception(e)
            ue_pc_alias = ue_pc_handler.ue_pc_host
            self._teardown_ue_pc(ue_pc_alias)
            raise e

    def _check_server_version_compatibility(self, ue_pc_handler):
        """
        Checks compatibility with connected ue_pc_server. If incompatible raises pc_server_exceptions.TestHandlingException
        :param ue_pc_handler: QxdmUePcHandler() obj
        :raises pc_server_exceptions.TestHandlingException
        :return: None
        """
        req_srv_ver = get_required_ue_pc_server_version()
        try:
            status, server_version = ue_pc_handler.send(TEST.GET_SERVER_VERSION)
            self.logger.info("TEST.GET_SERVER_VERSION status: {}".format(status))
            self.logger.info("UE PC SERVER VERSION: {}".format(server_version))
            if status and compare_versions(server_version, req_srv_ver):
                self.logger.info("ue_pc_server version verified successfully. Current:%s, Required:%s" % (server_version, req_srv_ver))
            else:
                raise pc_server_exceptions.TestHandlingException("UE PC Server preparation failed. ta_ue_plugin_qualcomm v.{} "
                                                                 "requires at least ue_pc_server v.{} "
                                                                 "MAKE SURE YOU ARE USING THE NEWEST VERSION OF UE_PC_SERVER".format(get_plugin_version(),
                                                                                                                                     req_srv_ver))
        except (ValueError, TypeError, TimeoutExceededException) as e:
            raise pc_server_exceptions.TestHandlingException("UE PC Server preparation failed:{}. Could not verify ue_pc_server version. "
                                                             "Check connection and/or configuration. "
                                                             "MAKE SURE YOU ARE USING THE NEWEST VERSION OF UE_PC_SERVER ({})".
                                                             format(str(e), req_srv_ver))

    def _build_dict_with_params(self, qxdm_ue_pc_handler):
        """
        Non-keyword method
        Method creates QxdmUePcHandler under dict
        :param ue_pc_handler:               QxdmUePcHandler() obj with params, from config
        :return:                            {'qxdm_ue_pc_handler': QxdmUePcHandler(), 'active_ues': []}
        """
        ue_pc = {
            'qxdm_ue_pc_handler': qxdm_ue_pc_handler,
            'active_ues': []
        }
        return ue_pc

    def shutdown(self):
        """Shutdown"""
        self.logger.debug("Qualcomm Ue pool shutdown self._taken_devices {} self.ue_pc_store: {}".format(self._taken_devices, self.ue_pc_store))
        for ue_name in list(self._taken_devices):
            self._return_device_to_available_devices(ue_name)
        for ip in list(self.ue_pc_store.keys()):
            del self.ue_pc_store[ip]

    def _return_device_to_available_devices(self, ue_name):
        ue = self._taken_devices[ue_name]
        ue_pc_alias = ue.ue_pc_handler.ue_pc_host
        if ue_name in self.ue_pc_store[ue_pc_alias]['active_ues']:
            self.ue_pc_store[ue_pc_alias]['active_ues'].remove(ue_name)
        current_active_ues = len(self.ue_pc_store[ue_pc_alias]['active_ues'])
        if current_active_ues == 0:
            self._teardown_ue_pc(ue_pc_alias)
        self.logger.info("Current number of UEs for ue_pc {}: {}".format(ue_pc_alias, current_active_ues))
        self.logger.debug("calling super _return_device_to_available_devices")
        super(QualcommUePool, self)._return_device_to_available_devices(ue_name)

    def _teardown_ue_pc(self, ue_pc_alias):
        ue_pc_handler = None
        try:
            ue_pc_handler = self.ue_pc_store[ue_pc_alias]['qxdm_ue_pc_handler']
            copy_logs_kwargs = {
                "login": get_vm_user(),
                "password": get_vm_password(),
                "remote_host": get_vm_ip_address(ifname='eth0'),
                "remote_port": get_vm_ssh_port(),
                "location": get_vm_test_logs_dir(),
                "alias": ue_pc_alias,
            }
            self.logger.debug("Downloading server logs via: '{}'".format(TEST.COPY_SERVER_LOGS))
            status, _ = ue_pc_handler.send(TEST.COPY_SERVER_LOGS, **copy_logs_kwargs)
            if status:
                self.logger.debug("Server logs from {} successfully downloaded".format(ue_pc_alias))
            else:
                self.logger.error("Error during downloading logs from {}".format(ue_pc_alias))
            status, _ = ue_pc_handler.send(TEST.FINISHED)
            if status:
                self.logger.info("Testcase on UE PC server '{}' finished.".format(ue_pc_alias))
                self.logger.info("Closing connection with UE PC '{}'".format(ue_pc_alias))
                del self.ue_pc_store[ue_pc_alias]
            else:
                self.logger.info("UE PC Server '{}' testcase finishing failed.".format(ue_pc_alias))
                raise pc_server_exceptions.TestHandlingException("Failed to properly handle test finishing procedure")
        except Exception as ex:
            self.logger.error("UE PC '{}' Teardown failed.".format(ue_pc_alias))
            self.logger.exception(ex)
            time.sleep(2)
            raise ex
        finally:
            if ue_pc_handler:
                ue_pc_handler.close_connection_with_ue_pc_server()

    def _withdraw_device_from_available_devices(self, ue_name, ue):
        self.ue_pc_store[ue.ue_pc_handler.ue_pc_host]['active_ues'].append(ue_name)
        super(QualcommUePool, self)._withdraw_device_from_available_devices(ue_name, ue)

    def forced_teardown(self):
        """
        Method forces teardown on all PC servers

        :return:        None
        """
        for ue_pc_alias in self.ue_pc_store:
            try:
                self._teardown_ue_pc(ue_pc_alias)
            except Exception:
                pass

    def _check_ue_serial_number(self, ue_pc_host, ue_serial_number):
        ue_pc_handler = self.ue_pc_store[ue_pc_host]['qxdm_ue_pc_handler']
        cmd = TEST.CHECK_SERIAL
        parameter = {"serial_number": ue_serial_number}
        try:
            status, messages = ue_pc_handler.send(cmd, **parameter)
            self.logger.info("TEST.CHECK_SERIAL status: {}".format(status))
            if not status or messages is "FAIL":
                self.logger.critical("Serial in abstract_lib_config.yml are different than in UE_PC.\
                                 Check the configuration!")
                self._teardown_ue_pc(ue_pc_host)
                raise InvalidConfigurationContent("Serial in abstract_lib_config.yml \
                                                   different than in UE_PC. \
                                                   Check the configuration!")
            else:
                self.logger.debug("Serial configuration from abstract_lib_config.yml \
                                   matches the one in UE_PC.")
        except AttributeError:
            self.logger.error("No ue_pc_handler found. Probably no qualcomm ue in ue pool found.")

    def _check_ue_com_port(self, ue_pc_host, ue_com_port):
        ue_pc_handler = self.ue_pc_store[ue_pc_host]['qxdm_ue_pc_handler']
        cmd = TEST.CHECK_COM_PORT
        parameter = {"com_port": ue_com_port}
        try:
            status, messages = ue_pc_handler.send(cmd, **parameter)
            self.logger.info("TEST.CHECK_COM_PORT status: {}".format(status))
            if not messages:
                messages = "Empty message"
            if "COM_PORT_NOT_DIAGNOSTIC" in messages:
                self.logger.warning("UE COM port in abstract_lib_config.yml may be not a diagnostic port.")
                self.logger.warning("Use this configuration only if you are sure it is valid.")
            elif not status or messages is "FAIL":
                self.logger.critical("COM port in abstract_lib_config.yml are different than in UE_PC.\
                                         Check the configuration!")
                self._teardown_ue_pc(ue_pc_host)
                raise InvalidConfigurationContent("COM port in abstract_lib_config.yml \
                                                           different than in UE_PC. \
                                                           Check the configuration!")
            else:
                self.logger.debug("COM port configuration from abstract_lib_config.yml \
                                           matches the one in UE_PC.")
        except AttributeError:
            self.logger.error("No ue_pc_handler found. Probably no qualcomm ue in ue pool found.")
